type T struct{ n int }

func (t *T) get() int {
	return t.n
}

func main() {
	defer func() {
		if recover() != nil {
			fmt.Println(1)
		} else {
			fmt.Println(0)
		}
	}()
	var p *T
	fmt.Println(p.get())
}

